28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.security.core.Authentication;
49	import org.springframework.security.core.context.SecurityContextHolder;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        HttpHeaders headers = new HttpHeaders();
115	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
116	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
117	        owner.setCity(canonicalCity(owner.getCity()));
118	        if (owner.getRegistrationDate() == null) {
119	            owner.setRegistrationDate(LocalDate.now());
120	        }
121	        if (isDailyRegistrationLimitReached()) {
122	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	        }
124	        if (isCityCapacityReached(owner.getCity())) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
128	            return new ResponseEntity<>(HttpStatus.CONFLICT);
129	        }
130	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
131	        owner.setMembershipNumber(membershipNumber);
132	        owner.setCustomerCode(customerCode(owner));
133	        owner.setMembershipTier(membershipNumber <= 100 ? "FOUNDING" : "STANDARD");
134	        owner.setNamesakeCount(namesakeCount(owner));
135	        owner.setSharesHousehold(sharesHousehold(owner));
136	        owner.setLocality(locality(owner));
137	        this.clinicService.saveOwner(owner);
138	        auditLogger.info("Owner created by user={} ownerId={} membershipNumber={}",
139	            currentUsername(), owner.getId(), owner.getMembershipNumber());
140	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
141	        headers.setLocation(UriComponentsBuilder.newInstance()
142	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
143	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
149	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
150	        if (currentOwner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        currentOwner.setAddress(ownerFieldsDto.getAddress());
154	        currentOwner.setCity(ownerFieldsDto.getCity());
155	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
156	        currentOwner.setLastName(ownerFieldsDto.getLastName());
157	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
158	        this.clinicService.saveOwner(currentOwner);
159	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Transactional
164	    @Override
165	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
166	        Owner owner = this.clinicService.findOwnerById(ownerId);
167	        if (owner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        this.clinicService.deleteOwner(owner);
171	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        HttpHeaders headers = new HttpHeaders();
182	        Pet pet = petMapper.toPet(petFieldsDto);
183	        owner.setId(ownerId);
184	        pet.setOwner(owner);
185	        pet.getType().setName(null);
186	        this.clinicService.savePet(pet);
187	        PetDto petDto = petMapper.toPetDto(pet);
188	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
189	            .buildAndExpand(pet.getId()).toUri());
190	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
196	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
197	        if (currentOwner != null) {
198	            Pet currentPet = this.clinicService.findPetById(petId);
199	            if (currentPet != null) {
200	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
201	                currentPet.setName(petFieldsDto.getName());
202	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
203	                this.clinicService.savePet(currentPet);
204	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
205	            }
206	        }
207	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
213	        HttpHeaders headers = new HttpHeaders();
214	        Visit visit = visitMapper.toVisit(visitFieldsDto);
215	        Pet pet = new Pet();
216	        pet.setId(petId);
217	        visit.setPet(pet);
218	        this.clinicService.saveVisit(visit);
219	        VisitDto visitDto = visitMapper.toVisitDto(visit);
220	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
221	            .buildAndExpand(visit.getId()).toUri());
222	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
223	    }
224	
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
229	        Owner owner = this.clinicService.findOwnerById(ownerId);
230	        if (owner != null) {
231	            Pet pet = owner.getPet(petId);
232	            if (pet != null) {
233	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
234	            }
235	        }
236	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	    }
238	
239	    /**
240	     * Determines whether an owner conflicting with the given one already exists, i.e. any existing
241	     * owner using the same telephone number.
242	     *
243	     * @param owner the candidate owner to check
244	     * @return {@code true} if another owner already uses the telephone number, {@code false} otherwise
245	     */
246	    /**
247	     * Builds the customer code assigned to a newly created owner, formatted as
248	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
249	     * already registered in the same city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
250	     *
251	     * @param owner the owner being created
252	     * @return the customer code for the owner
253	     */
254	    /**
255	     * Counts how many other owners already share the given owner's last name at the moment of
256	     * creation. The owner being created is not yet persisted and so is not included in the count.
257	     *
258	     * @param owner the owner being created
259	     * @return the number of existing owners with the same last name
260	     */
261	    /**
262	     * Determines whether the newly created owner shares a household with an existing owner, i.e.
263	     * whether another owner already has the same address and city. Both values are matched
264	     * case- and whitespace-insensitively.
265	     *
266	     * @param owner the owner being created
267	     * @return {@code true} if another owner already has the same address and city, {@code false} otherwise
268	     */
269	    private boolean sharesHousehold(Owner owner) {
270	        String address = normalize(owner.getAddress());
271	        String city = normalize(owner.getCity());
272	        return this.clinicService.findAllOwners().stream()
273	            .anyMatch(existing -> Objects.equals(address, normalize(existing.getAddress()))
274	                && Objects.equals(city, normalize(existing.getCity())));
275	    }
276	
277	    /**
278	     * Determines the locality of a newly created owner. The owner is {@code "local"} if their city
279	     * is the single most common city among the owners that already exist at the moment of creation
280	     * (i.e. strictly more owners live there than in any other city); otherwise the owner is
281	     * {@code "remote"}. When no owners yet exist, or when several cities are tied for most common,
282	     * the owner is {@code "remote"}. Cities are matched case- and whitespace-insensitively.
283	     *
284	     * @param owner the owner being created
285	     * @return {@code "local"} or {@code "remote"}
286	     */
287	    private String locality(Owner owner) {
288	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
289	            .map(existing -> normalize(existing.getCity()))
290	            .filter(Objects::nonNull)
291	            .collect(Collectors.groupingBy(city -> city, Collectors.counting()));
292	        if (countsByCity.isEmpty()) {
293	            return "remote";
294	        }
295	        long max = Collections.max(countsByCity.values());
296	        List<String> mostCommon = countsByCity.entrySet().stream()
297	            .filter(entry -> entry.getValue() == max)
298	            .map(Map.Entry::getKey)
299	            .toList();
300	        if (mostCommon.size() == 1 && mostCommon.get(0).equals(normalize(owner.getCity()))) {
301	            return "local";
302	        }
303	        return "remote";
304	    }
305	
306	    private int namesakeCount(Owner owner) {
307	        String lastName = owner.getLastName();
308	        return (int) this.clinicService.findAllOwners().stream()
309	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
310	            .count();
311	    }
312	
313	    private String customerCode(Owner owner) {
314	        String city = owner.getCity();
315	        long existingInCity = this.clinicService.findAllOwners().stream()
316	            .filter(existing -> Objects.equals(existing.getCity(), city))
317	            .count();
318	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
319	    }
320	
321	    /**
322	     * Determines the canonical spelling of the city for a newly created owner. If another owner
323	     * already lives in the same city (matched case- and whitespace-insensitively), that owner's exact
324	     * spelling of the city name is reused so that all owners in a city share a consistent value.
325	     * Otherwise the supplied city is title-cased (e.g. {@code "new york"} becomes {@code "New York"}).
326	     *
327	     * @param city the raw city as supplied when creating the owner, may be {@code null}
328	     * @return the canonical city spelling, or {@code null} if {@code city} was {@code null}
329	     */
330	    private String canonicalCity(String city) {
331	        if (city == null) {
332	            return null;
333	        }
334	        String normalized = normalize(city);
335	        for (Owner existing : this.clinicService.findAllOwners()) {
336	            if (existing.getCity() != null && normalized.equals(normalize(existing.getCity()))) {
337	                return existing.getCity();
338	            }
339	        }
340	        return titleCase(city);
341	    }
342	
343	    /**
344	     * Title-cases a value by upper-casing the first letter of every whitespace-separated word and
345	     * lower-casing the rest, collapsing any run of internal whitespace to a single space (e.g.
346	     * {@code "new  YORK city"} becomes {@code "New York City"}).
347	     *
348	     * @param value the value to title-case
349	     * @return the title-cased value
350	     */
351	    private static String titleCase(String value) {
352	        StringBuilder result = new StringBuilder();
353	        for (String word : value.strip().split("\\s+")) {
354	            if (word.isEmpty()) {
355	                continue;
356	            }
357	            if (result.length() > 0) {
358	                result.append(' ');
359	            }
360	            result.append(Character.toUpperCase(word.charAt(0)))
361	                .append(word.substring(1).toLowerCase(Locale.ROOT));
362	        }
363	        return result.toString();
364	    }
365	
366	    /**
367	     * Determines whether the maximum number of owners allowed to be registered on a single day has
368	     * already been reached. At most 20 owners may be created with today's registration date; once
369	     * that many exist, further registrations for today are rejected.
370	     *
371	     * @return {@code true} if 20 or more owners already have today's registration date
372	     */
373	    private boolean isDailyRegistrationLimitReached() {
374	        LocalDate today = LocalDate.now();
375	        long registeredToday = this.clinicService.findAllOwners().stream()
376	            .filter(existing -> today.equals(existing.getRegistrationDate()))
377	            .count();
378	        return registeredToday >= 20;
379	    }
380	
381	    /**
382	     * Determines whether the city of a newly created owner has already reached its capacity. At most
383	     * 8 owners may live in a single city; once a city already contains 8 owners, further registrations
384	     * for that city are rejected. Cities are matched case- and whitespace-insensitively so that
385	     * differing spellings of the same city name count towards the same limit.
386	     *
387	     * @param city the canonical city of the owner being created, may be {@code null}
388	     * @return {@code true} if the city already contains 8 or more owners, {@code false} otherwise
389	     */
390	    private boolean isCityCapacityReached(String city) {
391	        String normalized = normalize(city);
392	        long existingInCity = this.clinicService.findAllOwners().stream()
393	            .filter(existing -> Objects.equals(normalized, normalize(existing.getCity())))
394	            .count();
395	        return existingInCity >= 8;
396	    }
397	
398	    /**
399	     * Returns the name of the currently authenticated user, or {@code "anonymous"} when there is no
400	     * authentication in the security context.
401	     *
402	     * @return the authenticated user's name
403	     */
404	    private static String currentUsername() {
405	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
406	        return authentication != null ? authentication.getName() : "anonymous";
407	    }
408	
409	    private boolean isDuplicateOwner(Owner owner) {
410	        return this.clinicService.findAllOwners().stream()
411	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
412	    }
413	
414	    /**
415	     * Normalises a telephone number to digits only by stripping spaces, dashes and parentheses (and
416	     * any other non-digit characters). This is applied before storing the number and before the
417	     * telephone-uniqueness check, so that e.g. {@code "(613) 555-0100"} and {@code "6135550100"} are
418	     * stored identically and treated as the same number.
419	     *
420	     * @param telephone the raw telephone number, may be {@code null}
421	     * @return the digits-only telephone number, or {@code null} if {@code telephone} was {@code null}
422	     */
423	    private static String normalizeTelephone(String telephone) {
424	        if (telephone == null) {
425	            return null;
426	        }
427	        return telephone.replaceAll("[^0-9]", "");
428	    }
429	
430	    /**
431	     * Determines whether the given owner's email address is already used by another owner. An owner
432	     * without an email address never conflicts. The comparison is case-insensitive and ignores
433	     * surrounding or repeated whitespace, so e.g. {@code "  John.Smith@Example.com "} and
434	     * {@code "john.smith@example.com"} are treated as the same address.
435	     *
436	     * @param owner the candidate owner to check
437	     * @return {@code true} if another owner already uses the email address, {@code false} otherwise
438	     */
439	    private boolean isDuplicateEmail(Owner owner) {
440	        String email = normalize(owner.getEmail());
441	        if (email == null || email.isEmpty()) {
442	            return false;
443	        }
444	        return this.clinicService.findAllOwners().stream()
445	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
446	    }
447	
448	    /**
449	     * Normalises a value for case- and whitespace-insensitive duplicate detection: surrounding
450	     * whitespace is stripped, any run of internal whitespace is collapsed to a single space and all
451	     * letters are lower-cased. This is what makes {@code "  john   smith "} and {@code "John Smith"}
452	     * count as the same person (or, for e-mail, the same address) when detecting duplicates.
453	     *
454	     * @param value the raw value, may be {@code null}
455	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
456	     */
457	    private static String normalize(String value) {
458	        if (value == null) {
459	            return null;
460	        }
461	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
462	    }
463	}
