    void createOwnerSuccess() throws Exception {
        String body = """
            {"firstName":"George","lastName":"Testowner","address":"110 W. Liberty St.","city":"Madison","telephone":"9995550001"}
            """;
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(header().string("Location", org.hamcrest.Matchers.containsString("/api/owners/")))
            .andExpect(jsonPath("$.firstName").value("George"))
            .andExpect(jsonPath("$.initials").value("G.T."));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerReportsNamesakeCount() throws Exception {
        // A unique last name means no existing namesakes for the first owner; each subsequent owner
        // created with the same last name sees the count of the ones already registered.
        String lastName = "Namesaketestowner";
        String first = String.format("""
            {"firstName":"George","lastName":"%s","address":"110 W. Liberty St.","city":"Madison","telephone":"9995550101"}
            """, lastName);
        mvc.perform(post("/api/owners").content(first)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.namesakeCount").value(0));

        String second = String.format("""
            {"firstName":"Jane","lastName":"%s","address":"200 Main St.","city":"Madison","telephone":"9995550102"}
            """, lastName);
        mvc.perform(post("/api/owners").content(second)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.namesakeCount").value(1));

        String third = String.format("""
            {"firstName":"Jack","lastName":"%s","address":"300 Oak St.","city":"Madison","telephone":"9995550103"}
            """, lastName);
        mvc.perform(post("/api/owners").content(third)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.namesakeCount").value(2));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerDuplicateConflict() throws Exception {
        String lastName = "Duplicateowner";
        newOwner(lastName);
        String body = """
            {"firstName":"George","lastName":"%s","address":"110 W. Liberty St.","city":"Madison","telephone":"6085551023"}
            """.formatted(lastName);
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isConflict());
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerDuplicateEmailIgnoresCase() throws Exception {
        // First owner registers an email; second owner reuses it differing only by letter case,
        // with a distinct telephone so the email is the sole duplicate trigger.
        String first = """
            {"firstName":"George","lastName":"Emailone","address":"110 W. Liberty St.","city":"Madison","telephone":"9995550010","email":"John.Smith@Example.com"}
            """;
        mvc.perform(post("/api/owners").content(first)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated());

        String second = """
            {"firstName":"Jane","lastName":"Emailtwo","address":"200 Main St.","city":"Madison","telephone":"9995550011","email":"john.smith@example.com"}
            """;
        mvc.perform(post("/api/owners").content(second)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isConflict());
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerDuplicateTelephoneConflict() throws Exception {
        // A different last name but a telephone already used by another owner must be rejected.
        Owner existing = newOwner("Existingowner-" + System.nanoTime());
